using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml.Linq;
using System.IO.Compression;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using kok;
class ReadingRenewalTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Write(ZipArchive zip,string path,string text){using(var writer=new StreamWriter(zip.CreateEntry(path,path=="mimetype"?CompressionLevel.NoCompression:CompressionLevel.Optimal).Open(),new UTF8Encoding(false)))writer.Write(text);}
 static void Epub(string file,bool nav){using(var zip=ZipFile.Open(file,ZipArchiveMode.Create)){
  Write(zip,"mimetype","application/epub+zip");Write(zip,"META-INF/container.xml","<container xmlns='urn:oasis:names:tc:opendocument:xmlns:container'><rootfiles><rootfile full-path='OPS/book.opf'/></rootfiles></container>");
  Write(zip,"OPS/book.opf","<package xmlns='http://www.idpf.org/2007/opf'><metadata xmlns:dc='http://purl.org/dc/elements/1.1/'><dc:title>Real navigation</dc:title></metadata><manifest><item id='body' href='text/book%20body.xhtml' media-type='application/xhtml+xml'/><item id='nav' href='nav.xhtml' media-type='application/xhtml+xml' "+(nav?"properties='nav'":"")+"/><item id='ncx' href='toc.ncx' media-type='application/x-dtbncx+xml'/></manifest><spine toc='ncx'><itemref idref='body'/></spine></package>");
  Write(zip,"OPS/text/book body.xhtml","<!DOCTYPE html SYSTEM 'http://127.0.0.1:1/never.dtd'><html xmlns='http://www.w3.org/1999/xhtml'><head><title>Body title</title></head><body><h1>Body title</h1><p>Intro with&nbsp;spacing.</p><h2 id='one'>First heading</h2><p>First chapter content.</p>"+(nav?"<h2 id='two'>Second heading</h2>":"<a id='two'></a><h2>First heading</h2>")+"<p>Second chapter content.</p></body></html>");
  Write(zip,"OPS/nav.xhtml","<html xmlns='http://www.w3.org/1999/xhtml' xmlns:epub='http://www.idpf.org/2007/ops'><body><nav epub:type='toc'><ol><li><a href='text/book%20body.xhtml#one'>第一篇 · 真正目录</a><ol><li><a href='text/book%20body.xhtml#two'>第二节 · 嵌套目录</a></li></ol></li></ol></nav></body></html>");
  Write(zip,"OPS/toc.ncx","<ncx xmlns='http://www.daisy.org/z3986/2005/ncx/'><navMap><navPoint id='a'><navLabel><text>NCX 第一篇</text></navLabel><content src='text/book%20body.xhtml#one'/><navPoint id='b'><navLabel><text>NCX 第二节</text></navLabel><content src='text/book%20body.xhtml#two'/></navPoint></navPoint></navMap></ncx>");
 }}
 sealed class FastHandler:HttpMessageHandler {
  public int active,max,calls;public bool disabled;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Interlocked.Increment(ref calls);int count=Interlocked.Increment(ref active);max=Math.Max(max,count);try{var body=(Dictionary<string,object>)Library.Json.DeserializeObject(await request.Content.ReadAsStringAsync());disabled=body.ContainsKey("thinking")&&Convert.ToString(((Dictionary<string,object>)body["thinking"])["type"])=="disabled";var messages=(object[])body["messages"];var input=(object[])Library.Json.DeserializeObject(Convert.ToString(((Dictionary<string,object>)messages[1])["content"]));await Task.Delay(80,token);return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Library.Json.Serialize(new{choices=new[]{new{finish_reason="stop",message=new{content=Library.Json.Serialize(new{translations=input.Cast<Dictionary<string,object>>().Select(row=>new{id=row["id"],text="译："+row["text"]}).ToArray()})}}}}))};}finally{Interlocked.Decrement(ref active);}}
 }
 static void Main(string[] args){try{Run(args).GetAwaiter().GetResult();}catch(Exception error){Console.Error.WriteLine(error);Environment.ExitCode=1;}}
 static async Task Run(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);foreach(bool nav in new[]{true,false}){string file=Path.Combine(root,nav?"navigation.epub":"legacy.epub");Epub(file,nav);var book=Library.ReadBook(new Entry{path=file,name="Book",kind="book",ext="EPUB"});Check(book.chapters.Count==1&&book.toc.Count==2,"Navigation changed stable spine chapter indexes");Check(book.toc[0].source==(nav?"epub-nav":"epub-ncx")&&book.toc[1].depth==1,"Actual NAV/NCX hierarchy was not used");Check(book.toc[1].start>book.toc[0].start&&book.chapters[0].text.Substring(book.toc[1].start).StartsWith(nav?"Second heading":"First heading"),"Fragment navigation offset failed");Check(book.chapters[0].text.Contains("spacing"),"Safe XHTML entity handling failed");}
  string text=Path.Combine(root,"long-book.txt");File.WriteAllText(text,"序章\n\n"+String.Concat(Enumerable.Repeat("这是一段用于验证分页、字体与目录的正文。Reading should remain clear and comfortable.\n",180))+"\n第一章 春日\n\n"+String.Concat(Enumerable.Repeat("这是第一章的内容，应该正确分页并保存位置。\n",180))+"\n第二章 夏夜\n\n结尾内容。",new UTF8Encoding(false));var txt=Library.ReadBook(new Entry{path=text,name="Long book",kind="book",ext="TXT"});Check(txt.toc.Any(t=>t.title=="第一章 春日")&&txt.toc.Any(t=>t.title=="第二章 夏夜")&&txt.toc.All(t=>t.source=="text-heading"),"Chinese text headings were not recognized");
  string word=Path.Combine(root,"headings.docx");File.WriteAllBytes(word,TextDocumentExport.Export("# Primary heading\n\nBody text.\n\n## Secondary heading\n\nMore text.","Headings","docx"));XNamespace w="http://schemas.openxmlformats.org/wordprocessingml/2006/main";using(var zip=ZipFile.Open(word,ZipArchiveMode.Update)){XDocument doc;using(var reader=new StreamReader(zip.GetEntry("word/styles.xml").Open()))doc=XDocument.Parse(reader.ReadToEnd());doc.Root.Add(new XElement(w+"style",new XAttribute(w+"styleId","CustomTitle"),new XElement(w+"name",new XAttribute(w+"val","My style")),new XElement(w+"basedOn",new XAttribute(w+"val","Heading1"))));zip.GetEntry("word/styles.xml").Delete();Write(zip,"word/styles.xml",doc.ToString());using(var reader=new StreamReader(zip.GetEntry("word/document.xml").Open()))doc=XDocument.Parse(reader.ReadToEnd());doc.Descendants(w+"pStyle").First().SetAttributeValue(w+"val","CustomTitle");zip.GetEntry("word/document.xml").Delete();Write(zip,"word/document.xml",doc.ToString());}var docx=Library.ReadBook(new Entry{path=word,name="Word",kind="document",ext="DOCX"});Check(docx.toc.Count==2&&docx.toc[0].depth==0&&docx.toc[1].depth==1&&docx.toc[1].start>0,"Word outline/inherited heading styles failed");
  Console.WriteLine("PASS: real EPUB NAV/NCX hierarchy and fragment offsets, escaped paths/XHTML entities, Chinese headings, Word inherited heading styles and stable chapter indexes.");
  var handler=new FastHandler();var service=new TranslationService(Path.Combine(root,"mock-fast"),()=>handler);service.SaveConfig(new Dictionary<string,object>{{"endpoint","https://api.deepseek.com/v1"},{"model","mock-deepseek"},{"apiKey","dummy-reading-test-key"}});var input=Enumerable.Range(0,40).Select(n=>n+" "+new string('a',1000)).ToList();var result=await service.TranslateAsync(input,CancellationToken.None,(a,b)=>{},false,"简体中文",null,true);Check(handler.disabled&&handler.max==4&&handler.calls==5&&result.parts.Count==40,"Fast translation did not disable thinking, batch efficiently or bound concurrency");Console.WriteLine("PASS: DeepSeek fast request disables thinking and uses bounded four-worker batching, through an in-memory handler with no provider calls.");
 }
}
